import{_ as a,H as s,f as t,i as n}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"15 | ZAB协议：如何实现操作的顺序性？","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么Multi-Paxos无法保证操作顺序性？","slug":"为什么multi-paxos无法保证操作顺序性","link":"#为什么multi-paxos无法保证操作顺序性","children":[]},{"level":2,"title":"ZAB是如何实现操作的顺序性的？","slug":"zab是如何实现操作的顺序性的","link":"#zab是如何实现操作的顺序性的","children":[]},{"level":2,"title":"内容小结","slug":"内容小结","link":"#内容小结","children":[]},{"level":2,"title":"课堂思考","slug":"课堂思考","link":"#课堂思考","children":[]}],"relativePath":"分布式协议与算法实战/15-ZAB协议：如何实现操作的顺序性？.md","filePath":"分布式协议与算法实战/15-ZAB协议：如何实现操作的顺序性？.md","lastUpdated":1779818930000}'),i={name:"分布式协议与算法实战/15-ZAB协议：如何实现操作的顺序性？.md"};function p(E,e,o,l,r,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_15-zab协议-如何实现操作的顺序性" tabindex="-1">15 | ZAB协议：如何实现操作的顺序性？ <a class="header-anchor" href="#_15-zab协议-如何实现操作的顺序性" aria-label="Permalink to &quot;15 | ZAB协议：如何实现操作的顺序性？&quot;">​</a></h1><p>你好，我是韩健。</p><p>很多同学应该使用过ZooKeeper，它是一个开源的分布式协调服务，比如你可以用它进行配置管理、名字服务等等。在ZooKeeper中，数据是以节点的形式存储的。如果你要用ZooKeeper做配置管理，那么就需要在里面创建指定配置，假设创建节点&quot;/geekbang&quot;和&quot;/geekbang/time&quot;，步骤如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 0] create /geekbang 123</span></span>
<span class="line"><span>Created /geekbang</span></span>
<span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 1] create /geekbang/time 456</span></span>
<span class="line"><span>Created /geekbang/time</span></span></code></pre></div><p>我们分别创建了配置&quot;/geekbang&quot;和&quot;/geekbang/time&quot;，对应的值分别为123和456。那么在这里我提个问题：你觉得在ZooKeeper中，能用兰伯特的Multi-Paxos实现各节点数据的共识和一致吗？</p><p>当然不行。因为兰伯特的Multi-Paxos，虽然能保证达成共识后的值不再改变，但它不关心达成共识的值是什么，也无法保证各值（也就是操作）的顺序性。而这就是Zookeeper没有采用Multi-Paxos的原因，又是ZAB协议着力解决的，也是你理解ZAB协议的关键。</p><p>那么为了帮你更好地理解这个协议，接下来，我将分别以如何实现操作的顺序性、领导者选举、故障恢复、处理读写请求为例，具体讲解一下。希望你能在全面理解ZAB协议的同时，加深对Paxos算法的理解。</p><p>今天这节课，我会从ZAB协议的最核心设计目标（如何实现操作的顺序性）出发，带你了解它的基础原理。</p><p>老规矩，在开始今天的内容之前，我们先来看一道思考题：</p><p>假如节点A、B、C组成的一个分布式集群，我们要设计一个算法，来保证指令（比如X、Y）执行的顺序性，比如，指令X在指令Y之前执行，那么我们该如何设计这个算法呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/55dc6f6bf822db027858b8b4fdb89cc9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/55dc6f6bf822db027858b8b4fdb89cc9.jpg" alt=""></a></p><p>带着这个问题，我们进入今天的内容。</p><h2 id="为什么multi-paxos无法保证操作顺序性" tabindex="-1">为什么Multi-Paxos无法保证操作顺序性？ <a class="header-anchor" href="#为什么multi-paxos无法保证操作顺序性" aria-label="Permalink to &quot;为什么Multi-Paxos无法保证操作顺序性？&quot;">​</a></h2><p>刚刚我提到“Multi-Paxos无法保证操作的顺序性”。为了让你真正理解这个问题，我举个具体的例子演示一下（为了演示方便，我们假设当前所有节点上的被选定指令，最大序号都为100，那么新提议的指令对应的序号就会是101）。</p><p>首先节点A是领导者，提案编号为1，提议了指令X、Y，对应的序号分别为101和102，但是因为网络故障，指令只成功复制到了节点A。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/3ed203904d35eaf0bd5162262c1b4ef3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/3ed203904d35eaf0bd5162262c1b4ef3.jpg" alt=""></a></p><p>假设这时节点A故障了，新当选的领导者为节点B。节点B当选领导者后，需要先作为学习者了解目前已被选定的指令。节点B学习之后，发现当前被选定指令的最大序号为100（因为节点A故障了，它被选定指令的最大序号102，无法被节点B发现），那么它可以从序号101开始提议新的指令。这时它接收到客户端请求，并提议了指令Z，指令Z被成功复制到节点B、C。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/77f94aa5dec044ffc1a61547cb10f112.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/77f94aa5dec044ffc1a61547cb10f112.jpg" alt=""></a></p><p>假设这时节点B故障了，节点A恢复了，选举出领导者C后，节点B故障也恢复了。节点C当选领导者后，需要先作为学习者了解目前已被选定的指令，这时它执行Basic Paxos的准备阶段，就会发现之前选定的值（比如Z、Y），然后发送接受请求，最终在序号101、102处达成共识的指令是Z、Y。就像下图的样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/e6c27d879025ef6943a5985da1351bc4.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/e6c27d879025ef6943a5985da1351bc4.jpg" alt=""></a></p><p>在这里，你可以看到，原本预期的指令是X、Y，最后变成了Z、Y。讲到这儿，你应该可以知道，为什么用Multi-Paxos不能达到我们想要的结果了吧？</p><p>这个过程，其实很明显的验证了“Multi-Paxos虽然能保证达成共识后的值不再改变，但它不关心达成共识的值是什么。”</p><p>那么咱们接着回到开篇的问题，假设在ZooKeeper中直接使用了兰伯特的Multi-Paxos，这时创建节点&quot;/geekbang&quot;和&quot;/geekbang/time&quot;，那么就可能出现，系统先创建了节点&quot;/geekbang/time&quot;，这样肯定就出错了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 0] create /geekbang/time 456</span></span>
<span class="line"><span>Node does not exist: /geekbang/time</span></span></code></pre></div><p>因为创建节点&quot;/geekbang/time&quot;时，找不到节点&quot;/geekbang&quot;，所以就会创建失败。</p><p>在这里我多说几句，除了Multi-Paxos，兰伯特还有很多关于分布式的理论，这些理论都很经典（比如拜占庭将军问题），但也因为太早了，与实际场景结合的不多，所以后续的众多算法是在这个基础之上做了大量的改进（比如，PBFT、Raft等）。关于这一点，我在13讲也强调过，你需要注意一下。</p><p>另外我再延伸一下，其实在 <a href="https://www.semanticscholar.org/paper/Zab:-High-performance-broadcast-for-primary-backup-Junqueira-Reed/b02c6b00bd5dbdbd951fddb00b906c82fa80f0b3" target="_blank" rel="noreferrer">ZAB论</a> 文中，关于Paxos问题（Figure 1 ​​​​）的分析是有争议的。因为ZooKeeper当时应该考虑的是Multi-Paxos，而不是有多个提议者的Basic Paxos。而在Multi-Paxos中，领导者作为唯一提议者，是不存在同时多个提议者的情况。也就是说，Paxos（更确切的说是Multi-Paxos）无法保证操作的顺序性的问题是存在的，但原因不是ZAB论文中演示的原因，本质上是因为Multi-Paxos实现的是一系列值的共识，不关心最终达成共识的值是什么，不关心各值的顺序，就像我们在上面演示的过程那样。</p><p>那既然Multi-Paxos不行，ZooKeeper怎么实现操作的顺序性的呢?答案是它实现了ZAB协议。</p><p>你可能会说了：Raft可以实现操作的顺序性啊，为什么ZooKeeper不用Raft呢？这个问题其实比较简单，因为Raft出来的比较晚，直到2013年才正式提出，在2007年开发ZooKeeper的时候，还没有Raft呢。</p><h2 id="zab是如何实现操作的顺序性的" tabindex="-1">ZAB是如何实现操作的顺序性的？ <a class="header-anchor" href="#zab是如何实现操作的顺序性的" aria-label="Permalink to &quot;ZAB是如何实现操作的顺序性的？&quot;">​</a></h2><p>如果用一句话解释ZAB协议到底是什么，我觉得它是：能保证操作顺序性的，基于主备模式的原子广播协议。</p><p>接下来，我还是以X、Y指令为例具体演示一下，帮助你更好理解为什么ZAB能实现操作的顺序性（为了演示方便，我们假设节点A为主节点，节点B、C为备份节点）。</p><p>首先，需要你注意的是，在ZAB中，写操作必须在主节点（比如节点A）上执行。如果客户端访问的节点是备份节点（比如节点B），它会将写请求转发给主节点。如图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/770c39b4ea339799bc3ca4a0b0d8266f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/770c39b4ea339799bc3ca4a0b0d8266f.jpg" alt=""></a></p><p>接着，当主节点接收到写请求后，它会基于写请求中的指令（也就是X，Y），来创建一个提案（Proposal），并使用一个唯一的ID来标识这个提案。这里我说的唯一的ID就是指事务标识符（Transaction ID，也就是zxid），就像下图的样子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/d0063fa9275ce0a114ace27db326d19b.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/d0063fa9275ce0a114ace27db326d19b.jpg" alt=""></a></p><p>从图中你可以看到，X、Y对应的事务标识符分别为&lt;1, 1&gt;和&lt;1, 2&gt;，这两个标识符是什么含义呢？</p><p>你可以这么理解，事务标识符是64位的long型变量，有任期编号epoch和计数器counter两部分组成（为了形象和方便理解，我把epoch翻译成任期编号），格式为&lt;epoch, counter&gt;，高32位为任期编号，低32位为计数器：</p><ul><li><p>任期编号，就是创建提案时领导者的任期编号，需要你注意的是，当新领导者当选时，任期编号递增，计数器被设置为零。比如，前领导者的任期编号为1，那么新领导者对应的任期编号将为2。</p></li><li><p>计数器，就是具体标识提案的整数，需要你注意的是，每次领导者创建新的提案时，计数器将递增。比如，前一个提案对应的计数器值为1，那么新的提案对应的计数器值将为2。</p></li></ul><p>为什么要设计的这么复杂呢？因为事务标识符必须按照顺序、唯一标识一个提案，也就是说，事务标识符必须是唯一的、递增的。</p><p>在创建完提案之后，主节点会基于TCP协议，并按照顺序将提案广播到其他节点。这样就能保证先发送的消息，会先被收到，保证了消息接收的顺序性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/e525af146900c892e0c002affa77d496.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/e525af146900c892e0c002affa77d496.jpg" alt=""></a></p><p>你看这张图，X一定在Y之前到达节点B、C。</p><p>然后，当主节点接收到指定提案的“大多数”的确认响应后，该提案将处于提交状态（Committed），主节点会通知备份节点提交该提案。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/1d3950b6d91845789cce1f0569969419.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/1d3950b6d91845789cce1f0569969419.jpg" alt=""></a></p><p>在这里，需要你注意的是，主节点提交提案是有顺序性的。主节点根据事务标识符大小，按照顺序提交提案，如果前一个提案未提交，此时主节点是不会提交后一个提案的。也就是说，指令X一定会在指令Y之前提交。</p><p>最后，主节点返回执行成功的响应给节点B，节点B再转发给客户端。 <strong>你看，这样我们就实现了操作的顺序性，保证了指令X一定在指令Y之前执行。</strong></p><p>最后我想补充的是，当写操作执行完后，接下来你可能需要执行读操作了。你需要注意，为了提升读并发能力，Zookeeper提供的是最终一致性，也就是读操作可以在任何节点上执行，客户端会读到旧数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/d405381e5fad12730149baa4fae63e1c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%88%86%E5%B8%83%E5%BC%8F%E5%8D%8F%E8%AE%AE%E4%B8%8E%E7%AE%97%E6%B3%95%E5%AE%9E%E6%88%98/images/229975/d405381e5fad12730149baa4fae63e1c.jpg" alt=""></a></p><p>如果客户端必须要读到最新数据，怎么办呢？Zookeeper提供了一个解决办法，那就是sync命令。你可以在执行读操作前，先执行sync命令，这样客户端就能读到最新数据了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 2] sync /geekbang/time</span></span>
<span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 3] Sync returned 0</span></span>
<span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 3] get /geekbang/time</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>cZxid = 0x100000005</span></span>
<span class="line"><span>ctime = Mon Apr 20 21:19:28 HKT 2020</span></span>
<span class="line"><span>mZxid = 0x100000005</span></span>
<span class="line"><span>mtime = Mon Apr 20 21:19:28 HKT 2020</span></span>
<span class="line"><span>pZxid = 0x100000005</span></span>
<span class="line"><span>cversion = 0</span></span>
<span class="line"><span>dataVersion = 0</span></span>
<span class="line"><span>aclVersion = 0</span></span>
<span class="line"><span>ephemeralOwner = 0x0</span></span>
<span class="line"><span>dataLength = 3</span></span>
<span class="line"><span>numChildren = 0</span></span>
<span class="line"><span>[zk: 192.168.0.10:2181(CONNECTED) 4]</span></span></code></pre></div><h2 id="内容小结" tabindex="-1">内容小结 <a class="header-anchor" href="#内容小结" aria-label="Permalink to &quot;内容小结&quot;">​</a></h2><p>本节课我主要带你了解了为什么Multi-Paxos无法实现操作的顺序性，以及ZAB协议如何保证操作的顺序性。我希望你明确这样几个重点。</p><p>1.兰伯特的Multi-Paxos只考虑了如何实现共识，也就是如何就一系列值达成共识，未考虑如何实现各值（也就是操作）的顺序性。</p><p>2.ZAB是通过“一切以领导者为准”的强领导者模型和严格按照顺序处理、提交提案，来实现操作的顺序性的。</p><p>那么说到ZAB，很多同学可能有这样的疑问：为什么ZAB作者宣称 <a href="https://cwiki.apache.org/confluence/display/ZOOKEEPER/Zab+vs.+Paxos" target="_blank" rel="noreferrer">ZAB不是Paxos算法，</a> 但又有很多资料提到ZAB是Multi-Paxos算法呢？到底该怎么理解呢？</p><p>我的看法是，你可以把它理解为Multi-Paxos算法。因为技术是发展的，概念的内涵也在变化。Raft算法（主备、强领导者模型）与ZAB协议非常类似，它是作为共识算法和Multi-Paxos算法提出的。当它被广泛接受和认可后，共识算法的内涵也就丰富和发展了，不仅能实现一系列值的共识，还能保证值的顺序性。同样，Multi-Paxos算法不仅指代多次执行Basic Paxos的算法，还指代主备、强领导者模型的共识算法。</p><p>当然了，在学习技术过程中，我们不可避免的会遇到有歧义、有争议的信息，就像在11讲留言区中，有同学提到“从网上搜了搜相关资料，发现大部分资料将谣言传播等同于Gossip协议，也有把反熵等同于Gossip协议的，感到很迷惑”。</p><p>这就需要我们不仅要在平时工作和学习中，认真、全面的学习理论，掌握概念的内涵，还要能“包容”和“发展”着理解技术。</p><p>最后，在本节课我们了解了ZAB协议的最核心设计目标（如何实现操作的顺序性），那么既然“所有数据都是以主节点的数据为准的”，主节点（也就是领导者）那么重要，那当它崩溃了，该怎么处理呢？下节课，我会重点带你了解这部分内容。</p><h2 id="课堂思考" tabindex="-1">课堂思考 <a class="header-anchor" href="#课堂思考" aria-label="Permalink to &quot;课堂思考&quot;">​</a></h2><p>既然我提到在ZAB协议中，主节点是基于TCP协议来广播消息的，并保证了消息接收的顺序性。那么你不妨想想，如果ZAB采用的是UDP协议，能保证消息接收的顺序性吗？为什么呢？欢迎在留言区分享你的看法，与我一同讨论。</p><p>最后，感谢你的阅读，如果这节课让你有所收获，也欢迎你将它分享给更多的朋友。</p><hr><p>编辑角：目前课程已经结束了，为了交付更好的内容，《分布式协议与算法实战》于2020年4.26日启动迭代计划，15讲为迭代版本，后面也会对ZAB协议进行更细致化的讨论，敬请期待！</p>`,65)])])}const h=a(i,[["render",p]]);export{b as __pageData,h as default};
